import { Big } from "./bigint.js";
import { gcd, GcdProgram } from "./zk_gcd.js";

let compile = async function () {
  await GcdProgram.compile();
  compile = () => Promise.resolve();
};

test(
  "compile",
  async () => {
    await compile();
  },
  2 * 60 * 60_000
);

test(
  "gcd",
  async () => {
    await compile();
    let result = await gcd(
      Big.from(
        
      ),
      Big.from(
        
      )
    );
    console.log(result.publicOutput.assertSolved());
  },
  2 * 60 * 60 * 1000
);
